-- ---------------------------------------------------------------------------
-- CHECK constraints
-- ---------------------------------------------------------------------------

ALTER TABLE "payroll_year_end_declaration"
  ADD CONSTRAINT "payroll_year_end_declaration_year_range" CHECK ("year" BETWEEN 2000 AND 2100),
  ADD CONSTRAINT "payroll_year_end_declaration_object"
    CHECK (jsonb_typeof("declarations") = 'object'),
  ADD CONSTRAINT "payroll_year_end_declaration_updated_by_not_blank"
    CHECK (btrim("updated_by") <> '');

ALTER TABLE "payroll_year_end"
  ADD CONSTRAINT "payroll_year_end_year_range" CHECK ("year" BETWEEN 2000 AND 2100),
  ADD CONSTRAINT "payroll_year_end_snapshot_object" CHECK (jsonb_typeof("snapshot") = 'object'),
  ADD CONSTRAINT "payroll_year_end_table_id_not_blank" CHECK (btrim("table_id") <> ''),
  ADD CONSTRAINT "payroll_year_end_annual_tax_not_negative" CHECK ("annual_tax" >= 0),
  -- The settlement entry exists exactly when there is something to settle.
  ADD CONSTRAINT "payroll_year_end_settlement_entry_iff_difference"
    CHECK (("difference" = 0) = ("settlement_entry_id" IS NULL)),
  ADD CONSTRAINT "payroll_year_end_confirmed_by_not_blank" CHECK (btrim("confirmed_by") <> '');

-- ---------------------------------------------------------------------------
-- payroll_year_end: append-only (UPDATE / DELETE / TRUNCATE rejected)
-- ---------------------------------------------------------------------------

CREATE FUNCTION "ledger_payroll_year_end_reject_change"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'ledger guard: payroll_year_end is append-only (% of % rejected)', TG_OP, OLD."id";
END;
$$;

CREATE TRIGGER "payroll_year_end_reject_change"
  BEFORE UPDATE OR DELETE ON "payroll_year_end"
  FOR EACH ROW EXECUTE FUNCTION "ledger_payroll_year_end_reject_change"();

CREATE TRIGGER "payroll_year_end_reject_truncate"
  BEFORE TRUNCATE ON "payroll_year_end"
  FOR EACH STATEMENT EXECUTE FUNCTION "ledger_reject_truncate"();
